#!/usr/bin/env node
// Reproducible platform assets. One opaque 1024px master, no native project regeneration.
import { readFileSync, writeFileSync, readdirSync, existsSync, mkdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { draw, pngInfo } from './app-icons.mjs'
import { APP_ICON_VARIANTS } from '../src/lib/app-icon-variants.js'
import { decodePng, resizeRgba, encodeRgbPng } from '../../../../tools/nativeIconCodec.mjs'
const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const primary = APP_ICON_VARIANTS[0]
const master = decodePng(readFileSync(join(root, 'resources/red-fit-master.png')))
const put = (path, bytes) => { mkdirSync(dirname(path), { recursive: true }); writeFileSync(path, bytes) }
const icon = (rel, size, round = false) => put(join(root, rel), draw(primary, size, { round }))
function splash(rel, width, height) {
  const side = Math.round(Math.min(width, height) * .32)
  const mark = resizeRgba(master, side)
  const out = Buffer.alloc(width * height * 3)
  for (let i = 0; i < out.length; i += 3) { out[i] = 0; out[i + 1] = 0; out[i + 2] = 0 }
  const ox = Math.floor((width - side) / 2), oy = Math.floor((height - side) / 2)
  for (let y = 0; y < side; y++) for (let x = 0; x < side; x++) {
    const i = (y * side + x) * 4, o = ((y + oy) * width + x + ox) * 3
    for (let c = 0; c < 3; c++) out[o + c] = mark[i + c]
  }
  put(join(root, rel), encodeRgbPng(width, height, out))
}
icon('public/icon-180.png', 180)
icon('public/icon-512.png', 512)
icon('ios/App/App/Assets.xcassets/AppIcon.appiconset/AppIcon-512@2x.png', 1024)
icon('ios/App/Watch/Assets.xcassets/AppIcon.appiconset/AppIcon-1024.png', 1024)
for (const file of readdirSync(join(root, 'ios/App/App/Assets.xcassets/Splash.imageset'))) {
  if (file.endsWith('.png')) splash('ios/App/App/Assets.xcassets/Splash.imageset/' + file, 1366, 1366)
}
const res = 'android/app/src/main/res'
for (const folder of readdirSync(join(root, res))) {
  const dir = join(root, res, folder)
  if (!folder.startsWith('mipmap-') && !folder.startsWith('drawable')) continue
  for (const file of readdirSync(dir)) {
    if (!/^(ic_launcher(?:_round|_foreground|_background)?|splash)\.png$/.test(file)) continue
    const rel = res + '/' + folder + '/' + file
    const info = pngInfo(readFileSync(join(root, rel)))
    if (file === 'splash.png') splash(rel, info.width, info.height)
    else icon(rel, info.width, file.includes('_round'))
  }
}
// Keep the existing legacy PWA/desktop packaging references branded consistently.
for (const [file, size] of [['icon-192.png',192],['icon-512.png',512],['icon-maskable-512.png',512],['apple-touch-icon.png',180]]) {
  put(join(root, '../../../public/icons', file), draw(primary, size))
}
console.log('RED Fit primary web, iPhone, Watch, Android and reference assets generated')
// A flat silhouette for tinted Watch complications and Canvas share-card footers.
// Generated from the same master; pixel spans preserve the original negative space.
const grid = 128, small = resizeRgba(master, grid), spans = []
let minX = grid, minY = grid, maxX = 0, maxY = 0
for (let y = 0; y < grid; y++) {
  let start = -1
  for (let x = 0; x <= grid; x++) {
    const lit = x < grid && small[(y * grid + x) * 4] > 100 && small[(y * grid + x) * 4 + 2] > 100
    if (lit && start < 0) start = x
    if (!lit && start >= 0) {
      spans.push([start, y, x - start]); minX = Math.min(minX, start); minY = Math.min(minY, y)
      maxX = Math.max(maxX, x); maxY = Math.max(maxY, y + 1); start = -1
    }
  }
}
const normalized = spans.map(([x,y,w]) => [x-minX,y-minY,w])
const width = maxX-minX, height = maxY-minY
put(join(root, 'src/lib/brand-mark.js'), `// Generated by scripts/brand-red-fit.mjs from the original RED Fit master.\nexport const BRAND_WIDTH = ${width}\nexport const BRAND_HEIGHT = ${height}\nexport const BRAND_SPANS = ${JSON.stringify(normalized)}\n`)
const shape = normalized.map(([x,y,w]) => `M${x} ${y}h${w}v1h-${w}z`).join('')
put(join(root,'public/brand-mark.svg'), `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}"><path fill="currentColor" d="${shape}"/></svg>\n`)
// The historical Swift type name stays stable for both Watch extension targets.
const swiftFile = join(root,'ios/App/Watch/WidgetState.swift')
const swift = readFileSync(swiftFile,'utf8')
const at = swift.indexOf('struct OpenGymLogo: Shape {')
if (at < 0) throw new Error('Watch brand shape missing')
const replacement = `struct OpenGymLogo: Shape {
    func path(in rect: CGRect) -> Path {
        let spans: [(CGFloat, CGFloat, CGFloat)] = [
            ${normalized.map(row=>'('+row.join(', ')+')').join(',\n            ')}
        ]
        let scale = min(rect.width / ${width}, rect.height / ${height})
        let ox = rect.midX - ${width} * scale / 2
        let oy = rect.midY - ${height} * scale / 2
        var p = Path()
        for (x, y, w) in spans {
            p.addRect(CGRect(x: ox + x * scale, y: oy + y * scale, width: w * scale, height: scale))
        }
        return p
    }
}
`
put(swiftFile, swift.slice(0, at) + replacement)
put(join(root, 'src/assets/red-fit-icon.png'), draw(primary,180))
